def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a recursive descent parsing technique,
    which allows for clear separation of parsing rules for different JSON types.
    """

    class Tokenizer:
        def __init__(self, s):
            self.s = s
            self.pos = 0

        def next_token(self):
            while self.pos < len(self.s) and self.s[self.pos].isspace():
                self.pos += 1
            if self.pos == len(self.s):
                return None

            if self.s[self.pos] == '"':
                start = self.pos
                self.pos += 1
                while self.pos < len(self.s) and self.s[self.pos] != '"':
                    if self.s[self.pos] == '\\':
                        self.pos += 2
                    else:
                        self.pos += 1
                end = self.pos
                self.pos += 1
                return ('STRING', self.s[start:end])
            elif self.s[self.pos] in '-0123456789':
                start = self.pos
                while self.pos < len(self.s) and (self.s[self.pos] in '0123456789.eE+-'):
                    self.pos += 1
                return ('NUMBER', float(self.s[start:self.pos]) if '.' in self.s[start:self.pos] or 'e' in self.s[start:self.pos] else int(self.s[start:self.pos]))
            elif self.s[self.pos:self.pos + 4] == 'true':
                self.pos += 4
                return ('BOOL', True)
            elif self.s[self.pos:self.pos + 5] == 'false':
                self.pos += 5
                return ('BOOL', False)
            elif self.s[self.pos:self.pos + 4] == 'null':
                self.pos += 4
                return ('NULL', None)
            elif self.s[self.pos] == '{':
                self.pos += 1
                return ('LBRACE', '{')
            elif self.s[self.pos] == '}':
                self.pos += 1
                return ('RBRACE', '}')
            elif self.s[self.pos] == '[':
                self.pos += 1
                return ('LBRACKET', '[')
            elif self.s[self.pos] == ']':
                self.pos += 1
                return ('RBRACKET', ']')
            elif self.s[self.pos] == ',':
                self.pos += 1
                return ('COMMA', ',')
            elif self.s[self.pos] == ':':
                self.pos += 1
                return ('COLON', ':')
            else:
                raise ValueError(f'Unexpected character: {self.s[self.pos]}')

    def parse_value(tokenizer):
        token_type, value = tokenizer.next_token()
        if token_type is None:
            raise ValueError("Unexpected end of input")
        elif token_type == 'STRING':
            return value[1:-1].encode().decode('unicode_escape')
        elif token_type == 'NUMBER':
            return value
        elif token_type == 'BOOL':
            return value
        elif token_type == 'NULL':
            return value
        elif token_type == 'LBRACE':
            return parse_object(tokenizer)
        elif token_type == 'LBRACKET':
            return parse_array(tokenizer)
        else:
            raise ValueError(f'Unexpected token: {token_type}')

    def parse_object(tokenizer):
        obj = {}
        while True:
            token = tokenizer.next_token()
            if token is None:
                raise ValueError("Unexpected end of input in object")
            token_type, key = token
            if token_type == 'RBRACE':
                break
            if token_type != 'STRING':
                raise ValueError("Expected STRING key in object")
            key = key[1:-1].encode().decode('unicode_escape')
            token = tokenizer.next_token()
            if token is None or token[0] != 'COLON':
                raise ValueError("Expected COLON after key in object")
            value = parse_value(tokenizer)
            obj[key] = value

            token = tokenizer.next_token()
            if token is None:
                raise ValueError("Unexpected end of input in object")
            if token[0] == 'RBRACE':
                break
            elif token[0] != 'COMMA':
                raise ValueError("Expected COMMA or RBRACE in object")

        return obj

    def parse_array(tokenizer):
        array = []
        while True:
            token = tokenizer.next_token()
            if token is None:
                raise ValueError("Unexpected end of input in array")
            if token[0] == 'RBRACKET':
                break
            tokenizer.pos -= len(token[1])  # Rewind for parse_value to consume the value
            value = parse_value(tokenizer)
            array.append(value)

            token = tokenizer.next_token()
            if token is None:
                raise ValueError("Unexpected end of input in array")
            if token[0] == 'RBRACKET':
                break
            elif token[0] != 'COMMA':
                raise ValueError("Expected COMMA or RBRACKET in array")

        return array

    tokenizer = Tokenizer(s)
    result = parse_value(tokenizer)
    if tokenizer.next_token() is not None:
        raise ValueError("Extra data after JSON input")
    return result

def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a state machine approach,
    where the parser manages its state while iterating through the input characters.
    """

    class JSONParser:
        def __init__(self, s):
            self.s = s
            self.length = len(s)
            self.index = 0

        def parse(self):
            self.skip_whitespace()
            if self.index >= self.length:
                raise ValueError("Empty string")
            char = self.s[self.index]
            if char == '{':
                return self.parse_object()
            elif char == '[':
                return self.parse_array()
            elif char == '"':
                return self.parse_string()
            elif char in '-0123456789':
                return self.parse_number()
            elif self.s.startswith("true", self.index):
                self.index += 4
                return True
            elif self.s.startswith("false", self.index):
                self.index += 5
                return False
            elif self.s.startswith("null", self.index):
                self.index += 4
                return None
            else:
                raise ValueError(f"Unexpected character: {char}")

        def skip_whitespace(self):
            while self.index < self.length and self.s[self.index].isspace():
                self.index += 1

        def parse_string(self):
            self.index += 1  # Skip the opening quote
            start_index = self.index
            result = []
            while self.index < self.length:
                char = self.s[self.index]
                if char == '"':
                    result.append(self.s[start_index:self.index])
                    self.index += 1  # Skip the closing quote
                    return ''.join(result)
                elif char == '\\':
                    result.append(self.s[start_index:self.index])
                    self.index += 1
                    if self.index < self.length:
                        escape_char = self.s[self.index]
                        if escape_char in '"\\/bfnrt':
                            result.append({
                                '"': '"',
                                '\\': '\\',
                                '/': '/',
                                'b': '\b',
                                'f': '\f',
                                'n': '\n',
                                'r': '\r',
                                't': '\t'
                            }[escape_char])
                            self.index += 1
                        else:
                            raise ValueError(f"Invalid escape: {escape_char}")
                    start_index = self.index
                else:
                    self.index += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start_index = self.index
            if self.s[self.index] == '-':
                self.index += 1
            while self.index < self.length and self.s[self.index] in '0123456789':
                self.index += 1
            if self.index < self.length and self.s[self.index] == '.':
                self.index += 1
                while self.index < self.length and self.s[self.index] in '0123456789':
                    self.index += 1
            if self.index < self.length and self.s[self.index] in 'eE':
                self.index += 1
                if self.index < self.length and self.s[self.index] in '+-':
                    self.index += 1
                while self.index < self.length and self.s[self.index] in '0123456789':
                    self.index += 1
            number_str = self.s[start_index:self.index]
            if '.' in number_str or 'e' in number_str or 'E' in number_str:
                return float(number_str)
            return int(number_str)

        def parse_object(self):
            obj = {}
            self.index += 1  # Skip the opening brace
            self.skip_whitespace()
            while self.index < self.length and self.s[self.index] != '}':
                key = self.parse_string()
                self.skip_whitespace()
                if self.index >= self.length or self.s[self.index] != ':':
                    raise ValueError("Missing colon after key")
                self.index += 1  # Skip the colon
                self.skip_whitespace()
                value = self.parse()
                obj[key] = value
                self.skip_whitespace()
                if self.index < self.length and self.s[self.index] == ',':
                    self.index += 1  # Skip the comma
                    self.skip_whitespace()
                elif self.s[self.index] != '}':
                    raise ValueError("Expected comma or closing brace")
            if self.index < self.length:
                self.index += 1  # Skip the closing brace
            return obj

        def parse_array(self):
            array = []
            self.index += 1  # Skip the opening bracket
            self.skip_whitespace()
            while self.index < self.length and self.s[self.index] != ']':
                value = self.parse()
                array.append(value)
                self.skip_whitespace()
                if self.index < self.length and self.s[self.index] == ',':
                    self.index += 1  # Skip the comma
                    self.skip_whitespace()
                elif self.s[self.index] != ']':
                    raise ValueError("Expected comma or closing bracket")
            if self.index < self.length:
                self.index += 1  # Skip the closing bracket
            return array

    parser = JSONParser(s)
    result = parser.parse()
    parser.skip_whitespace()
    if parser.index < parser.length:
        raise ValueError("Extra data after JSON input")
    return result

def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a state machine approach,
    where the parser maintains a state and transitions based on input characters.
    """

    class ParseError(Exception):
        pass

    def parse_string(index):
        nonlocal s
        if s[index] != '"':
            raise ParseError("Invalid string start")
        index += 1
        start = index
        while index < len(s):
            if s[index] == '"':
                return s[start:index], index + 1
            elif s[index] == '\\':
                index += 2
            else:
                index += 1
        raise ParseError("Unterminated string")

    def parse_number(index):
        nonlocal s
        start = index
        if s[index] in ('-', '+'):
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        return float(s[start:index]) if '.' in s[start:index] or 'e' in s[start:index] else int(s[start:index]), index

    def parse_value(index):
        nonlocal s
        char = s[index]
        if char == '"':
            return parse_string(index)
        elif char.isdigit() or char in ('-', '+'):
            return parse_number(index)
        elif s.startswith('true', index):
            return True, index + 4
        elif s.startswith('false', index):
            return False, index + 5
        elif s.startswith('null', index):
            return None, index + 4
        elif char == '{':
            return parse_object(index + 1)
        elif char == '[':
            return parse_array(index + 1)
        else:
            raise ParseError(f"Unexpected character: {char}")

    def parse_object(index):
        obj = {}
        while index < len(s):
            key, index = parse_string(index)
            index = skip_whitespace(index)
            if s[index] != ':':
                raise ParseError("Expected ':' after key")
            index += 1  # Skip ':'
            index = skip_whitespace(index)
            value, index = parse_value(index)
            obj[key] = value

            index = skip_whitespace(index)
            if s[index] == '}':
                return obj, index + 1
            elif s[index] == ',':
                index += 1  # Skip ','
                index = skip_whitespace(index)
            else:
                raise ParseError(f"Expected ',' or '}}' but found: {s[index]}")
        raise ParseError("Unexpected end of input in object")

    def parse_array(index):
        arr = []
        while index < len(s):
            value, index = parse_value(index)
            arr.append(value)

            index = skip_whitespace(index)
            if s[index] == ']':
                return arr, index + 1
            elif s[index] == ',':
                index += 1  # Skip ','
                index = skip_whitespace(index)
            else:
                raise ParseError(f"Expected ',' or ']' but found: {s[index]}")
        raise ParseError("Unexpected end of input in array")

    def skip_whitespace(index):
        while index < len(s) and s[index].isspace():
            index += 1
        return index

    result, index = parse_value(skip_whitespace(0))
    if index < len(s):
        raise ParseError("Extra data after JSON input")
    return result

def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a finite state machine approach,
    where different states correspond to different parsing contexts (object, array, value).
    """

    class State:
        START, STRING, NUMBER, TRUE, FALSE, NULL, OBJECT, ARRAY, ESCAPE = range(9)

    def next_token():
        nonlocal pos, state, current_string, current_value

        while pos < len(s) and s[pos].isspace():
            pos += 1

        if pos == len(s):
            return None

        char = s[pos]

        if char == '"':
            pos += 1
            state = State.STRING
            current_string = ''
            return 'STRING_START'

        elif char.isdigit() or char == '-' or char == '+':
            state = State.NUMBER
            current_value = char
            pos += 1
            while pos < len(s) and (s[pos].isdigit() or s[pos] in '.eE+-'):
                current_value += s[pos]
                pos += 1
            return 'NUMBER'

        elif s.startswith('true', pos):
            pos += 4
            state = State.TRUE
            return 'TRUE'

        elif s.startswith('false', pos):
            pos += 5
            state = State.FALSE
            return 'FALSE'

        elif s.startswith('null', pos):
            pos += 4
            state = State.NULL
            return 'NULL'

        elif char == '{':
            pos += 1
            state = State.OBJECT
            return 'LBRACE'

        elif char == '}':
            pos += 1
            return 'RBRACE'

        elif char == '[':
            pos += 1
            state = State.ARRAY
            return 'LBRACKET'

        elif char == ']':
            pos += 1
            return 'RBRACKET'

        elif char == ',':
            pos += 1
            return 'COMMA'

        elif char == ':':
            pos += 1
            return 'COLON'

        elif char == '\\':
            pos += 1
            state = State.ESCAPE
            return 'ESCAPE'

        raise ValueError(f'Unexpected character: {char}')

    def parse_value():
        token = next_token()
        if token is None:
            raise ValueError("Unexpected end of input")

        if token == 'STRING_START':
            return parse_string()
        elif token == 'NUMBER':
            try:
                return float(current_value) if '.' in current_value else int(current_value)
            except ValueError:
                raise ValueError("Invalid number format")
        elif token == 'TRUE':
            return True
        elif token == 'FALSE':
            return False
        elif token == 'NULL':
            return None
        elif token == 'LBRACE':
            return parse_object()
        elif token == 'LBRACKET':
            return parse_array()
        else:
            raise ValueError(f'Unexpected token: {token}')

    def parse_string():
        result = ''
        global pos
        while pos < len(s):
            char = s[pos]
            if char == '"':
                pos += 1
                return result
            elif char == '\\':
                pos += 1
                if pos < len(s):
                    escape_char = s[pos]
                    if escape_char in '"\\/bfnrt':
                        result += {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}[escape_char]
                        pos += 1
                    else:
                        raise ValueError("Invalid escape sequence")
            else:
                result += char
                pos += 1
        raise ValueError("Unterminated string")

    def parse_object():
        obj = {}
        while True:
            token = next_token()
            if token == 'RBRACE':
                return obj
            if token != 'STRING_START':
                raise ValueError("Expected STRING key in object")

            key = parse_string()
            if next_token() != 'COLON':
                raise ValueError("Expected COLON after key in object")
            obj[key] = parse_value()

            if next_token() == 'RBRACE':
                return obj

    def parse_array():
        array = []
        while True:
            token = next_token()
            if token == 'RBRACKET':
                return array
            pos -= len(token)  # Rewind for parse_value to consume the value
            array.append(parse_value())

            if next_token() == 'RBRACKET':
                return array

    pos = 0
    global current_string, current_value
    current_string = ''
    current_value = ''

    result = parse_value()
    if next_token() is not None:
        raise ValueError("Extra data after JSON input")
    return result

def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a stack-based approach. This method utilizes
    a stack to manage context during parsing and handles different JSON structures by pushing and
    popping context as needed.
    """

    def parse_string():
        nonlocal index
        result = ""
        index += 1  # Skip opening quote
        while index < len(s):
            char = s[index]
            if char == '"':
                index += 1  # Skip closing quote
                return result
            elif char == '\\':
                index += 1  # Skip escape character
                if index < len(s):
                    result += s[index]
            else:
                result += char
            index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[start] in "-0123456789":
            index += 1
            while index < len(s) and s[index] in "0123456789.eE+-":
                index += 1
            number_str = s[start:index]
            return int(number_str) if '.' not in number_str else float(number_str)
        raise ValueError("Invalid number format")

    def parse_value():
        nonlocal index
        char = s[index]

        if char == '"':
            return parse_string()
        elif char in "-0123456789":
            return parse_number()
        elif s.startswith("true", index):
            index += 4
            return True
        elif s.startswith("false", index):
            index += 5
            return False
        elif s.startswith("null", index):
            index += 4
            return None
        elif char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        raise ValueError("Unexpected character")

    def parse_object():
        nonlocal index
        obj = {}
        index += 1  # Skip opening brace
        while index < len(s):
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == '}':
                index += 1  # Skip closing brace
                return obj
            key = parse_string()
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] != ':':
                raise ValueError("Expected ':' after key")
            index += 1  # Skip colon
            value = parse_value()
            obj[key] = value

            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == '}':
                index += 1  # Skip closing brace
                return obj
            elif s[index] == ',':
                index += 1  # Skip comma
            else:
                raise ValueError("Expected ',' or '}' in object")

    def parse_array():
        nonlocal index
        arr = []
        index += 1  # Skip opening bracket
        while index < len(s):
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == ']':
                index += 1  # Skip closing bracket
                return arr
            value = parse_value()
            arr.append(value)

            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == ']':
                index += 1  # Skip closing bracket
                return arr
            elif s[index] == ',':
                index += 1  # Skip comma
            else:
                raise ValueError("Expected ',' or ']' in array")

    index = 0
    return parse_value()
